package com.sakalti.modifier;
import net.minecraft.world.effect.*; import net.minecraft.world.entity.LivingEntity; import slimeknights.tconstruct.library.modifiers.Modifier; import slimeknights.tconstruct.library.tools.context.ToolAttackContext; import slimeknights.tconstruct.library.tools.nbt.IToolStackView;
public class WeakBurnModifier extends Modifier { @Override public int afterEntityHit(IToolStackView tool,int level,ToolAttackContext ctx,float damage){LivingEntity t=ctx.getLivingTarget();if(t!=null&&!t.level().isClientSide)t.addEffect(new MobEffectInstance(MobEffects.WEAKNESS,40,Math.max(0,level-1)));return 0;}}
